pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 fundAmt, address nonOwner, uint256 cmdValue, uint8 cmdFlag) public {
        // restrict to admissible domain: fundAmt>0, nonOwner != Owner, cmdValue <= fundAmt
        vm.assume(fundAmt > 0);
        vm.assume(nonOwner != c.Owner());
        vm.assume(cmdValue <= fundAmt);

        // fund the contract and an adversarial helper
        address owner = c.Owner();
        vm.deal(owner, fundAmt);
        vm.prank(owner);
        (bool s,) = address(c).call{value: fundAmt}("");
        require(s, "fund failed");

        // deploy a helper that always reverts on incoming calls (unchecked return)
        Reverter rev = new Reverter();

        // Owner calls Command with the fuzzed cmd values, targeting the helper
        vm.prank(owner);
        if(cmdFlag % 2 == 0) {
            c.Command{value: cmdValue}(address(rev), "");
        } else {
            c.Command{value: cmdValue}(address(rev), hex"dead");
        }

        // Now, check: a non-owner call to withdraw must fail (revert) on the reference contract.
        bool ok = true;
        vm.prank(nonOwner);
        try c.withdraw() { ok = true; } catch { ok = false; }

        // universal rule: for every state reachable via Command, a non-owner withdraw attempt reverts.
        assertTrue(!ok, "non-owner withdraw should fail on reference");
    }
}

contract Reverter {
    fallback() external payable {
        revert("helper reverts");
    }
}

