pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract AdversarialCallee {
    event BalanceIncrease(uint256 delta);
    fallback() external payable {
        emit BalanceIncrease(msg.value);
    }
}

contract InvMutTest is Test {
    C c;
    AdversarialCallee callee;

    function setUp() public {
        c = new C();
        callee = new AdversarialCallee();
    }

    function testFuzz_property(uint128 msgValue, bytes calldata data) public {
        // Restrict to admissible domain: msgValue > 0 (so forwarded value matters) and not exceeding a bound to keep balances manageable
        vm.assume(msgValue > 0);
        vm.assume(msgValue <= 1 ether);

        // The contract's owner (msg.sender of setUp) is the owner of C
        // Fund the owner to send ETH with Command
        vm.deal(address(this), msgValue);

        uint256 calleeBalanceBefore = address(callee).balance;
        uint256 contractBalanceBefore = address(c).balance;

        // Owner calls Command with value
        c.Command{value: msgValue}(address(callee), data);

        uint256 calleeBalanceAfter = address(callee).balance;
        uint256 contractBalanceAfter = address(c).balance;

        uint256 calleeDelta = calleeBalanceAfter - calleeBalanceBefore;
        uint256 contractDelta = contractBalanceBefore - contractBalanceAfter;

        // General rule: the ETH forwarded to callee (calleeDelta) equals the ETH sent with the call (contractDelta).
        // The buggy version forwards 0, so calleeDelta is 0 while contractDelta is msgValue, breaking equality.
        assertTrue(calleeDelta == contractDelta);
    }
}

