        bool reverted = false;
        (bool success, ) = address(c).call{value: sendValue}(abi.encodeWithSignature("multiplicate(address)", adr));
        if (!success) {
            reverted = true;
        }
        assert(!(sendValue < preBalance && !reverted));
    }
    receive() external payable {}
}

